57	    const base = H*0.2;
58	    const arc = H*0.015 * Math.pow(Math.sin(Math.PI*x/W), 2);
59	    return base + arc;
60	  },
61	  get bottomY(){ return H*0.94 },
62	  // 世界深度z(0=玩家处, 1=极远) → 屏幕Y
63	  // 使用平方曲线让近处空间更多、远处压缩
64	  screenY(z){
65	    const hMid = this.horizonY(W*0.5);
66	    return hMid + Math.pow(z, 0.7) * (this.bottomY - hMid);
67	  },
68	  // 屏幕Y → 世界深度z
69	  worldZ(sy){
70	    const hMid = this.horizonY(W*0.5);
71	    return Math.pow((sy - hMid) / (this.bottomY - hMid), 1/0.7);
72	  },
73	  // 缩放因子: 1=玩家处, <1=远处
74	  scale(sy){
75	    const hMid = this.horizonY(W*0.5);
76	    const pSy = this.screenY(0.62); // 玩家深度参考点
77	    if(sy <= hMid) return 0.08;
78	    const t = (sy - hMid) / (pSy - hMid);
79	    return Math.max(0.08, Math.min(2.5, t));
80	  },
