324	  X.fillStyle=gd; X.fillRect(0,topY+slOff,W,botY-topY-slOff);
325	
326	  // ── 弧形地平线（轨道汇聚到消失点） ──
327	  // 在弧形地平线下方填充轨道区域
328	  X.fillStyle='rgba(90,85,75,0.5)';
329	  X.beginPath();
330	  X.moveTo(0,topY+slOff);
331	  // 沿地平线画弧
332	  for(let x=0;x<=W;x+=2){
333	    X.lineTo(x,VP.horizonY(x)+slOff);
334	  }
335	  X.lineTo(W,botY); X.lineTo(0,botY); X.fill();
336	
337	  // ── 高架桥墩 ──
338	  if(slope>0.12){
339	    const nPiers=6;
340	    for(let i=0;i<nPiers;i++){
341	      const px=W*(i+0.3)/nPiers;
342	      const pH=slope*H*0.25;
343	      const pTop=topY+slOff;
344	      X.fillStyle='#4a4a4a';
345	      X.fillRect(px-W*0.008,pTop,W*0.016,pH);
346	      X.fillStyle='#3a3a3a';
347	      X.fillRect(px-W*0.015,pTop,W*0.03,W*0.006);
348	    }
349	  }
350	
351	  // ── 三条铁轨（透视汇聚） ──
352	  const lanes=[-1,0,1];
353	  // 先画枕木(远处密、近处疏)
354	  for(let z=0.02;z<0.98;z+=0.012){
355	    const sy=VP.screenY(z)+slOff;
356	    if(sy>botY||sy<topY) continue;
357	    const sc=VP.scale(sy);
358	    const tieW=W*0.09*sc;
359	    const tieH=H*0.004*sc;
360	    const tieX=VP.vx;
361	    const alpha=CL((z-0.02)/0.15,0,1);
362	    X.fillStyle=`rgba(80,55,30,${0.7*alpha})`;
363	    X.fillRect(tieX-tieW/2,sy-tieH/2,tieW,tieH);
364	  }
365	
366	  // 钢轨(每个跑道2根)
367	  for(const lane of lanes){
368	    for(let rail=0;rail<2;rail++){
369	      const offset=(rail-0.5)*W*0.018;
370	      X.strokeStyle='#8899aa';
371	      X.beginPath();
372	      for(let z=0.02;z<1.0;z+=0.03){
373	        const sy=VP.screenY(z)+slOff;
374	        const sc=VP.scale(sy);
375	        const lx=VP.vx+lane*W*0.09*sc*3.2+offset*sc;
376	        if(z===0.02) X.moveTo(lx,sy); else X.lineTo(lx,sy);
377	      }
378	      X.lineWidth=1.2; X.stroke();
379	      // 高光
380	      X.strokeStyle='#ccddee';
381	      X.lineWidth=0.5;
382	      X.beginPath();
383	      for(let z=0.02;z<1.0;z+=0.03){
384	        const sy=VP.screenY(z)+slOff;
385	        const sc=VP.scale(sy);
386	        const lx=VP.vx+lane*W*0.09*sc*3.2+(offset-0.5)*sc;
387	        if(z===0.02) X.moveTo(lx,sy); else X.lineTo(lx,sy);
388	      }
389	      X.stroke();
390	    }
391	  }
392	
393	  // ── 路灯(沿轨道) ──
394	  for(let z=0.08;z<0.9;z+=0.15){
395	    const sy=VP.screenY(z)+slOff;
396	    if(sy>botY-10||sy<topY+10) continue;
397	    const sc=VP.scale(sy);
398	    const poleX=VP.vx+W*0.21*sc;
399	    X.fillStyle='#555';
400	    X.fillRect(poleX-W*0.004*sc,sy-H*0.06*sc,W*0.008*sc,H*0.06*sc);
401	    X.fillStyle='#ffeaa7';
402	    X.beginPath();
403	    X.arc(poleX,sy-H*0.06*sc,W*0.005*sc,0,Math.PI*2);
404	    X.fill();
405	  }
406	
407	  // ── 速度线(向前运动感) ──
408	  for(const sl of speedLines){
409	    const alpha=sl.life/sl.maxL;
410	    X.strokeStyle=`rgba(255,255,255,${alpha*0.5})`;
411	    X.lineWidth=1;
412	    X.beginPath();
413	    X.moveTo(sl.x,sl.y);
414	    X.lineTo(sl.x,sl.y+sl.len);
415	    X.stroke();
416	  }
417	
418	  // ── 距离标记柱(沿轨道边缘，显示前进感) ──
419	  const markSpacing=0.08; // 世界深度间距
420	  for(let mz=(trackOff*0.01)%markSpacing;mz<0.95;mz+=markSpacing){
421	    const msy=VP.screenY(mz)+slOff;
422	    if(msy>botY-3||msy<topY+3) continue;
423	    const msc=VP.scale(msy);
424	    const distLabel=Math.floor(mz*1000);
425	    // 左侧标记柱
426	    const mlx=VP.vx-W*0.14*msc;
427	    X.fillStyle='#fff';
428	    X.fillRect(mlx-W*0.003*msc,msy-H*0.04*msc,W*0.006*msc,H*0.04*msc);
429	    X.fillStyle='#e74c3c';
430	    X.beginPath();X.arc(mlx,msy-H*0.04*msc,W*0.006*msc,0,Math.PI*2);X.fill();
431	    // 右侧标记柱
432	    const mrx=VP.vx+W*0.14*msc;
433	    X.fillStyle='#fff';
434	    X.fillRect(mrx-W*0.003*msc,msy-H*0.04*msc,W*0.006*msc,H*0.04*msc);
435	    X.fillStyle='#e74c3c';
436	    X.beginPath();X.arc(mrx,msy-H*0.04*msc,W*0.006*msc,0,Math.PI*2);X.fill();
437	  }
438	
439	  // 坡道标记
440	  if(Math.abs(slope)>0.08){
441	    const mx=W/2, my=botY-15;
442	    X.fillStyle='rgba(255,255,255,0.5)';
443	    X.font=`${W*0.028}px Arial`; X.textAlign='center';
444	    X.fillText(slope>0?'▲  上坡  ↑':'▼  下坡  ↓',mx,my);
445	  }
446	}
