452	function drawPlayer(sx,sy,sc,state){
453	  X.save(); X.translate(sx,sy); X.scale(sc,sc);
454	  const u=W*0.028; // 基础单位
455	  const fl=P.inv>0&&Math.floor(P.inv*18)%2===0;
456	
457	  // ── 阴影 ──
458	  if(state!=='jump'){
459	    X.fillStyle='rgba(0,0,0,0.35)';
460	    X.beginPath(); X.ellipse(0,u*1.5,u*2.8,u*0.7,0,0,Math.PI*2); X.fill();
461	  } else {
462	    X.fillStyle='rgba(0,0,0,0.12)';
463	    X.beginPath(); X.ellipse(0,u*3.5,u*1.2,u*0.3,0,0,Math.PI*2); X.fill();
464	  }
465	
466	  if(state==='slide'){
467	    // ══ 滑铲姿态 ══
468	    // 压低身体
469	    X.fillStyle=fl?'#fff':'#1a1a2e';
470	    X.fillRect(-u*3,-u*0.6,u*6,u*1.1);
471	    // 连帽衫
472	    X.fillStyle=fl?'#fff':'#e74c3c';
473	    X.fillRect(-u*2.8,-u*0.4,u*4,u*0.9);
474	    // 头
475	    X.fillStyle=fl?'#fff':'#f5c6a0';
476	    X.beginPath();X.arc(-u*2,-u*0.1,u*1.1,0,Math.PI*2);X.fill();
477	    // 帽子
478	    X.fillStyle=fl?'#fff':'#e74c3c';
479	    X.beginPath();X.arc(-u*2,-u*0.5,u*1.2,Math.PI,Math.PI*2);X.fill();
480	    // 伸出的腿
481	    X.fillStyle='#1a1a2e';
482	    X.fillRect(-u*3,u*0.2,u*2.5,u*0.6);
483	    X.fillRect(u*0.5,u*0.2,u*2.5,u*0.6);
484	    // 鞋
485	    X.fillStyle='#eee';
486	    X.fillRect(-u*3.2,u*0.6,u*1.8,u*0.45);
487	    X.fillRect(u*0.7,u*0.6,u*1.8,u*0.45);
488	  } else {
489	    // ══ 跑步/跳跃姿态 ══
490	    const cyc=frm*0.14;
491	    const armL=Math.sin(cyc)*u*1.6;
492	    const armR=Math.sin(cyc+Math.PI)*u*1.6;
493	    const legL=Math.sin(cyc)*u*1.8;
494	    const legR=Math.sin(cyc+Math.PI)*u*1.8;
495	    const bob=Math.abs(Math.sin(cyc*2))*u*0.25;
496	    const bodyY=-u*2.2-bob;
497	
498	    // 左腿
499	    X.fillStyle='#1a1a30';
500	    X.save();X.translate(-u*0.7,bodyY+u*2.6);X.rotate(legL*0.07);
501	    X.fillRect(-u*0.5,0,u*1,u*2.4);
502	    X.fillStyle='#eee';X.fillRect(-u*0.6,u*2.1,u*1.2,u*0.5);
503	    X.restore();
504	    // 右腿
505	    X.fillStyle='#1a1a30';
506	    X.save();X.translate(u*0.7,bodyY+u*2.6);X.rotate(legR*0.07);
507	    X.fillRect(-u*0.5,0,u*1,u*2.4);
508	    X.fillStyle='#eee';X.fillRect(-u*0.6,u*2.1,u*1.2,u*0.5);
509	    X.restore();
510	    // 躯干
511	    X.fillStyle=fl?'#fff':'#2c3e50';
512	    X.fillRect(-u*1.4,bodyY,u*2.8,u*2.8);
513	    // 连帽衫
514	    X.fillStyle=fl?'#fff':'#e74c3c';
515	    X.fillRect(-u*1.7,bodyY,u*3.4,u*2);
516	    X.fillStyle=fl?'#fff':'#c0392b';
517	    X.fillRect(-u*1.5,bodyY+u*1.7,u*3,u*1.1);
518	    // 左臂
519	    X.fillStyle=fl?'#fff':'#e74c3c';
520	    X.save();X.translate(-u*1.7,bodyY+u*0.4);X.rotate(-0.25+armL*0.05);
521	    X.fillRect(-u*0.4,0,u*0.8,u*2.1);
522	    X.fillStyle=fl?'#fff':'#f5c6a0';
523	    X.beginPath();X.arc(0,u*2.2,u*0.45,0,Math.PI*2);X.fill();
524	    X.restore();
525	    // 右臂
526	    X.fillStyle=fl?'#fff':'#e74c3c';
527	    X.save();X.translate(u*1.7,bodyY+u*0.4);X.rotate(0.25+armR*0.05);
528	    X.fillRect(-u*0.4,0,u*0.8,u*2.1);
529	    X.fillStyle=fl?'#fff':'#f5c6a0';
530	    X.beginPath();X.arc(0,u*2.2,u*0.45,0,Math.PI*2);X.fill();
531	    X.restore();
532	    // 头
533	    const hY=bodyY-u*1.4;
534	    X.fillStyle=fl?'#fff':'#f5c6a0';
535	    X.beginPath();X.arc(0,hY,u*1.25,0,Math.PI*2);X.fill();
536	    // 帽子
537	    X.fillStyle=fl?'#fff':'#e74c3c';
538	    X.beginPath();X.arc(0,hY-u*0.25,u*1.35,Math.PI,Math.PI*2);X.fill();
539	    X.fillStyle=fl?'#fff':'#c0392b';
540	    X.fillRect(-u*1.5,hY-u*0.25,u*3,u*0.25);
541	    X.fillStyle=fl?'#fff':'#e74c3c';
542	    X.beginPath();X.moveTo(-u*1.7,hY-u*0.25);X.lineTo(u*1.7,hY-u*0.25);
543	    X.lineTo(u*1.2,hY-u*0.8);X.lineTo(-u*1.2,hY-u*0.8);X.fill();
544	    // 头发
545	    X.fillStyle='#1a1a1a';
546	    X.beginPath();X.arc(0,hY+u*0.7,u*1,-0.15,Math.PI+0.15);X.fill();
547	  }
548	
549	  // ── 道具光环 ──
550	  if(P.skate&&P.skateT>0){
551	    X.fillStyle='rgba(46,204,113,0.35)';
552	    X.beginPath();X.arc(0,u*0.5,u*3.5,0,Math.PI*2);X.fill();
553	    X.fillStyle='#2ecc71';
554	    X.fillRect(-u*3.5,u*1.3,u*7,u*0.35);
555	    X.fillRect(-u*2.5,u*1.5,u*1.2,u*0.25);
556	    X.fillRect(u*1.3,u*1.5,u*1.2,u*0.25);
557	  }
558	  if(P.magnet&&P.magnetT>0){
559	    const p=Math.sin(frm*0.25)*0.3+0.5;
560	    X.strokeStyle=`rgba(52,152,219,${p})`;X.lineWidth=2.5;
561	    X.beginPath();X.arc(0,u*0.3,u*4.5,0,Math.PI*2);X.stroke();
562	  }
563	
564	  X.restore();
565	}
