571	function drawOb(ob,sx,sy,sc){
572	  X.save(); X.translate(sx,sy);
573	  const u=W*0.025*sc;
574	
575	  // ── 操作提示标记（接近玩家时） ──
576	  const pSy=VP.screenY(P.z);
577	  if(sy>pSy-H*0.06&&sy<pSy+H*0.03&&!ob.passed){
578	    // 底部指示器
579	    const hintY=u*4;
580	    if(ob.action===0){
581	      // 滑铲提示: 向下的箭头
582	      X.fillStyle='rgba(52,152,219,0.8)';
583	      X.beginPath();X.moveTo(0,hintY+u*2);X.lineTo(-u*2.5,hintY-u);X.lineTo(u*2.5,hintY-u);X.fill();
584	      X.fillStyle='#fff'; X.font=`bold ${u*1.5}px Arial`; X.textAlign='center';
585	      X.fillText('↓',0,hintY+u*0.3);
586	    } else if(ob.action===1){
587	      // 跳跃提示: 向上的箭头
588	      X.fillStyle='rgba(46,204,113,0.8)';
589	      X.beginPath();X.moveTo(0,hintY-u*2);X.lineTo(-u*2.5,hintY+u);X.lineTo(u*2.5,hintY+u);X.fill();
590	      X.fillStyle='#fff'; X.font=`bold ${u*1.5}px Arial`; X.textAlign='center';
591	      X.fillText('↑',0,hintY+u*0.8);
592	    } else {
593	      // 换道提示: 左右箭头
594	      X.fillStyle='rgba(231,76,60,0.8)';
595	      X.font=`bold ${u*2}px Arial`; X.textAlign='center';
596	      X.fillText('← →',0,hintY+u*0.5);
597	    }
598	  }
599	
600	  switch(ob.type){
601	    // ── 低矮障碍(滑铲) ──
602	    case 'barrier':
603	      // 黑白条纹横杆
604	      X.fillStyle='#e74c3c';
605	      X.fillRect(-u*5,-u*0.6,u*10,u*1.2);
606	      X.fillStyle='#fff';
607	      for(let i=-4;i<5;i+=2) X.fillRect(u*i,-u*0.6,u*2,u*1.2);
608	      X.fillStyle='#333';
609	      X.fillRect(-u*4.2,u*0.6,u*0.4,u*2.5);
610	      X.fillRect(u*3.8,u*0.6,u*0.4,u*2.5);
611	      break;
612	    case 'pipe':
613	      // 灰色圆管
614	      X.fillStyle='#95a5a6';
615	      X.fillRect(-u*4.5,-u*0.5,u*9,u*1);
616	      X.fillStyle='#bdc3c7';
617	      X.fillRect(-u*4.5,-u*0.5,u*9,u*0.25);
618	      X.fillStyle='#7f8c8d';
619	      X.fillRect(-u*4.5,u*0.3,u*9,u*0.2);
620	      break;
621	    case 'lowFence':
622	      // 黄色低围栏+竖杆
623	      X.fillStyle='#f39c12';
624	      for(let fx=-u*4;fx<=u*4;fx+=u*1.5){ X.fillRect(fx,-u*1.8,u*0.25,u*1.8); }
625	      X.fillRect(-u*4.3,-u*1.6,u*8.6,u*0.3);
626	      X.fillRect(-u*4.3,-u*0.6,u*8.6,u*0.3);
627	      break;
628	    case 'wire':
629	      // 橙色电缆线
630	      X.strokeStyle='#e67e22';X.lineWidth=u*0.6;
631	      X.beginPath();X.moveTo(-u*4.5,-u*0.2);X.quadraticCurveTo(0,-u*0.8,u*4.5,-u*0.2);X.stroke();
632	      X.fillStyle='#e67e22';
633	      X.beginPath();X.arc(-u*4.2,-u*0.2,u*0.5,0,Math.PI*2);X.fill();
634	      X.beginPath();X.arc(u*4.2,-u*0.2,u*0.5,0,Math.PI*2);X.fill();
635	      break;
636	
637	    // ── 中等障碍(跳跃) ──
638	    case 'signal':
639	      // 信号灯箱+闪烁灯
640	      X.fillStyle='#2c3e50';
641	      X.fillRect(-u*2,-u*4.5,u*4,u*4.5);
642	      X.fillStyle='#e74c3c';
643	      X.beginPath();X.arc(0,-u*3,u*1.1,0,Math.PI*2);X.fill();
644	      X.fillStyle='#2ecc71';
645	      X.beginPath();X.arc(0,-u*1.5,u*1.1,0,Math.PI*2);X.fill();
646	      if(Math.sin(frm*0.2)>0){ X.fillStyle='#ff0000';X.beginPath();X.arc(0,-u*3,u*0.7,0,Math.PI*2);X.fill(); }
647	      X.fillStyle='#555';X.fillRect(-u*0.3,u*0,u*0.6,u*2.5);
648	      break;
649	    case 'ties':
650	      // 枕木堆叠
651	      X.fillStyle='#8B4513';
652	      X.fillRect(-u*3,-u*1.2,u*6,u*0.5);
653	      X.fillRect(-u*2.5,-u*1.8,u*5,u*0.5);
654	      X.fillRect(-u*2,-u*2.4,u*4,u*0.5);
655	      X.fillStyle='#6B3410';
656	      X.fillRect(-u*1.5,-u*3,u*3,u*0.5);
657	      break;
658	    case 'barrel':
659	      // 油桶
660	      X.fillStyle='#e74c3c';
661	      X.fillRect(-u*1.8,-u*3.5,u*3.6,u*3.8);
662	      X.fillStyle='#c0392b';
663	      X.fillRect(-u*1.8,-u*3.5,u*3.6,u*0.8);
664	      X.fillRect(-u*1.8,u*0,u*3.6,u*0.5);
665	      X.fillStyle='#fff';
666	      X.fillRect(-u*1.2,-u*2.5,u*2.4,u*1.2);
667	      break;
668	    case 'coneWall':
669	      // 锥桶排
670	      X.fillStyle='#ff6600';
671	      for(let cx=-u*3;cx<=u*3;cx+=u*1.8){
672	        X.beginPath();X.moveTo(cx,-u*3);X.lineTo(cx-u*1.2,u*0.5);X.lineTo(cx+u*1.2,u*0.5);X.fill();
673	        X.fillStyle='#fff';
674	        X.fillRect(cx-u*0.6,-u*1.8,u*1.2,u*0.3);
675	        X.fillStyle='#ff6600';
676	      }
677	      break;
678	
679	    // ── 高大障碍(换道) ──
680	    case 'cart':
681	      // 黄色维修平板车(占据整道)
682	      X.fillStyle='#f1c40f';
683	      X.fillRect(-u*4,-u*3,u*8,u*3.5);
684	      X.fillStyle='#e67e22';
685	      X.fillRect(-u*3.5,-u*2.5,u*7,u*2.5);
686	      X.fillStyle='#333';
687	      X.beginPath();X.arc(-u*2.5,u*1.2,u*1,0,Math.PI*2);X.fill();
688	      X.beginPath();X.arc(u*2.5,u*1.2,u*1,0,Math.PI*2);X.fill();
689	      X.fillStyle='#f39c12';
690	      X.font=`bold ${u*1.2}px Arial`;X.textAlign='center';
691	      X.fillText('⚠',0,-u*1);
692	      break;
693	    case 'tower':
694	      // 信号塔基座(高大)
695	      X.fillStyle='#7f8c8d';
696	      X.fillRect(-u*3,-u*5.5,u*6,u*6);
697	      X.fillStyle='#666';
698	      for(let ty=-u*5;ty<0;ty+=u*1.3){ X.fillRect(-u*3.5,ty,u*7,u*0.25); }
699	      X.fillStyle='#e74c3c';
700	      X.beginPath();X.arc(0,-u*4.5,u*0.8,0,Math.PI*2);X.fill();
701	      break;
702	    case 'worker':
703	      // 工人(左右移动)
