881	function roundRect(x,y,w,h,r){
882	  X.beginPath();X.moveTo(x+r,y);X.lineTo(x+w-r,y);
883	  X.quadraticCurveTo(x+w,y,x+w,y+r);X.lineTo(x+w,y+h-r);
884	  X.quadraticCurveTo(x+w,y+h,x+w-r,y+h);X.lineTo(x+r,y+h);
885	  X.quadraticCurveTo(x,y+h,x,y+h-r);X.lineTo(x,y+r);
886	  X.quadraticCurveTo(x,y,x+r,y);X.closePath();
887	}
