889	function drawStar(cx,cy,oR,iR,pts){
890	  X.beginPath();
891	  for(let i=0;i<pts*2;i++){
892	    const r=i%2===0?oR:iR, a=i*Math.PI/pts-Math.PI/2;
893	    const x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r;
894	    i===0?X.moveTo(x,y):X.lineTo(x,y);
895	  }
896	  X.closePath();
897	}
