1008	function inp(act){
1009	  if(state===GS.MENU){ if(act==='start'||act==='jump'||act==='slide') startGame(); return; }
1010	  if(state===GS.DEAD){ if(act==='start'||act==='jump'||act==='slide') startGame(); return; }
1011	  switch(act){
1012	    case 'left': P.tgtLane=Math.max(-1,P.tgtLane-1); break;
1013	    case 'right': P.tgtLane=Math.min(1,P.tgtLane+1); break;
1014	    case 'jump':
1015	      if(!P.jumping&&!P.sliding){ P.jumping=true;P.vy=-10.5;P.jH=0;sJump();
1016	        const jx=VP.laneX(P.curLX,VP.screenY(P.z)),jy=VP.screenY(P.z);
1017	        addParts(jx,jy,6,'#fff',1);
1018	      }
1019	      break;
1020	    case 'slide':
1021	      if(!P.jumping&&!P.sliding){ P.sliding=true;P.slideT=0.5;sSlide(); }
1022	      break;
1023	  }
1024	}
