extends Node2D

@onready var player: CharacterBody2D = $World/Player
@onready var obstacle_spawner: Node2D = $World/ObstacleSpawner
@onready var pickup_spawner: Node2D = $World/PickupSpawner
@onready var train_spawner: Node2D = $World/TrainSpawner

var slope: float = 0.0
var target_slope: float = 0.0
var slope_timer: float = 0.0
var frame_count: int = 0
var shake_intensity: float = 0.0
var shake_timer: float = 0.0
var slow_mo: float = 0.0
var last_heal_distance: float = 0.0

func _ready() -> void:
	GameManager.game_started.connect(_on_game_started)
	GameManager.game_ended.connect(_on_game_ended)
	if player:
		player.died.connect(_on_player_died)

func _process(delta: float) -> void:
	if GameManager.state != GameManager.State.PLAY:
		return

	if slow_mo > 0:
		delta *= 0.25
		slow_mo -= delta

	delta = min(delta, 0.1)
	frame_count += 1

	_update_slope(delta)
	_update_speed(delta)
	_update_distance(delta)
	_update_auto_heal()
	_update_shake(delta)

	queue_redraw()

func _update_slope(delta: float) -> void:
	slope_timer -= delta
	if slope_timer <= 0:
		target_slope = randf_range(-0.5, 0.5)
		slope_timer = randf_range(3.0, 7.0)
	slope = move_toward(slope, target_slope, delta * 0.45)

func _update_speed(delta: float) -> void:
	var speed_ramp := 1.0 + min(GameManager.total_distance / 12000.0, 1.0) * 0.35
	GameManager.base_speed = 200.0 * speed_ramp
	GameManager.current_speed = GameManager.base_speed * (1.0 - slope * 0.22)
	GameManager.current_speed = clamp(GameManager.current_speed, 160.0, 480.0)

func _update_distance(delta: float) -> void:
	var dd := GameManager.current_speed * delta
	GameManager.total_distance += dd
	GameManager.distance += dd
	GameManager.score += dd * 0.5
	GameManager.score_changed.emit(GameManager.score)

func _update_auto_heal() -> void:
	var checkpoint := floor(GameManager.total_distance / 500.0) * 500.0
	if checkpoint > last_heal_distance:
		last_heal_distance = checkpoint
		if player and player.hp < player.max_hp:
			player.heal(1)

func _update_shake(delta: float) -> void:
	if shake_timer > 0:
		shake_timer -= delta
	else:
		shake_intensity = 0.0

func add_shake(intensity: float, duration: float) -> void:
	shake_intensity = intensity
	shake_timer = duration

func _on_game_started() -> void:
	last_heal_distance = 0.0
	slope = 0.0
	target_slope = 0.0
	slope_timer = randf_range(3.0, 7.0)
	slow_mo = 0.0
	shake_intensity = 0.0
	shake_timer = 0.0

func _on_game_ended() -> void:
	add_shake(8.0, 0.4)
	slow_mo = 0.5

func _on_player_died() -> void:
	GameManager.end_game()

extends Node2D

func _draw() -> void:
	var slope: float = 0.0
	var parent := get_parent()
	if parent and parent is Node2D and parent.has_method("add_shake"):
		slope = parent.slope

	var slope_offset: float = slope * get_viewport().get_visible_rect().size.y * 0.1
	_draw_gravel(slope_offset)
	_draw_tracks(slope_offset)
	_draw_ties(slope_offset)
	_draw_lamps(slope_offset)
	_draw_distance_markers(slope_offset)

func _draw_gravel(slope_offset: float) -> void:
	var top_y := Perspective.screen_y(1.0) + slope_offset
	var bot_y := Perspective.screen_y(0.0)
	var w := get_viewport().get_visible_rect().size.x
	draw_rect(Rect2(0, top_y, w, bot_y - top_y), Color("#8a8a7a"))

func _draw_tracks(slope_offset: float) -> void:
	var lanes := [-1, 0, 1]
	var w := get_viewport().get_visible_rect().size.x
	for lane in lanes:
		for rail in range(2):
			var offset := (float(rail) - 0.5) * w * 0.018
			var points: PackedVector2Array = []
			for i in range(1, 100):
				var depth := float(i) / 100.0
				if depth < 0.02 or depth > 0.98:
					continue
				var sy := Perspective.screen_y(depth) + slope_offset
				var sc := Perspective.scale_at_sy(sy)
				var lx := Perspective.lane_x(float(lane), sy) + offset * sc
				points.append(Vector2(lx, sy))
			if points.size() > 1:
				draw_polyline(points, Color("#8899aa"), 1.2)

func _draw_ties(slope_offset: float) -> void:
	var bot_y := Perspective.screen_y(0.0)
	var top_y := Perspective.screen_y(1.0)
	var w := get_viewport().get_visible_rect().size.x
	for i in range(1, 83):
		var depth := float(i) * 0.012
		if depth >= 0.98:
			continue
		var sy := Perspective.screen_y(depth) + slope_offset
		if sy > bot_y or sy < top_y:
			continue
		var sc := Perspective.scale_at_sy(sy)
		var tie_w := w * 0.09 * sc
		var tie_h := get_viewport().get_visible_rect().size.y * 0.004 * sc
		var alpha := clamp((depth - 0.02) / 0.15, 0.0, 1.0)
		draw_rect(Rect2(w / 2.0 - tie_w / 2, sy - tie_h / 2, tie_w, tie_h), Color(0.314, 0.216, 0.118, 0.7 * alpha))

func _draw_lamps(slope_offset: float) -> void:
	var bot_y := Perspective.screen_y(0.0)
	var top_y := Perspective.screen_y(1.0)
	var w := get_viewport().get_visible_rect().size.x
	for i in range(1, 7):
		var depth := float(i) * 0.15
		if depth >= 0.9:
			continue
		var sy := Perspective.screen_y(depth) + slope_offset
		if sy > bot_y - 10 or sy < top_y + 10:
			continue
		var sc := Perspective.scale_at_sy(sy)
		var pole_x := w / 2.0 + w * 0.21 * sc
		draw_rect(Rect2(pole_x - w * 0.004 * sc, sy - get_viewport().get_visible_rect().size.y * 0.06 * sc, w * 0.008 * sc, get_viewport().get_visible_rect().size.y * 0.06 * sc), Color("#555555"))
		draw_circle(Vector2(pole_x, sy - get_viewport().get_visible_rect().size.y * 0.06 * sc), w * 0.005 * sc, Color("#ffeaa7"))

func _draw_distance_markers(slope_offset: float) -> void:
	var mark_spacing := 0.08
	var offset := fmod(GameManager.total_distance * 0.01, mark_spacing)
	var bot_y := Perspective.screen_y(0.0)
	var top_y := Perspective.screen_y(1.0)
	var w := get_viewport().get_visible_rect().size.x
	var mz := offset
	while mz < 0.95:
		var msy := Perspective.screen_y(mz) + slope_offset
		if msy <= bot_y - 3 and msy >= top_y + 3:
			var msc := Perspective.scale_at_sy(msy)
			var vx := w / 2.0
