@export var pickup_scene: PackedScene

var spawn_timer: float = 0.0

func _ready() -> void:
	spawn_timer = randf_range(2.0, 4.5)

func _process(delta: float) -> void:
	if GameManager.state != GameManager.State.PLAY:
		return

	spawn_timer -= delta
	if spawn_timer <= 0:
		spawn_pickup()
		spawn_timer = randf_range(2.0, 4.5)

func spawn_pickup() -> void:
