		draw_rect(Rect2(pole_x - size.x * 0.004 * sc, sy - size.y * 0.06 * sc, size.x * 0.008 * sc, size.y * 0.06 * sc), Color(0.333, 0.333, 0.333, 1.0))
		draw_circle(Vector2(pole_x, sy - size.y * 0.06 * sc), size.x * 0.005 * sc, Color(1.0, 0.914, 0.655, 1.0))

func _draw_distance_markers(size: Vector2, slope_offset: float) -> void:
	var mark_spacing := 0.08
	var offset := fmod(GameManager.total_distance * 0.01, mark_spacing)
	var bot_y := Perspective.screen_y(0.0)
	var top_y := Perspective.screen_y(1.0)
	var mz := offset
	while mz < 0.95:
		var msy := Perspective.screen_y(mz) + slope_offset
		if msy <= bot_y - 3.0 and msy >= top_y + 3.0:
			var msc := Perspective.scale_at_sy(msy)
			var vx := size.x / 2.0
			var mlx := vx - size.x * 0.14 * msc
			draw_rect(Rect2(mlx - size.x * 0.003 * msc, msy - size.y * 0.04 * msc, size.x * 0.006 * msc, size.y * 0.04 * msc), Color.WHITE)
			draw_circle(Vector2(mlx, msy - size.y * 0.04 * msc), size.x * 0.006 * msc, Color(0.906, 0.298, 0.235, 1.0))
		mz += mark_spacing

extends Node2D

@export var train_scene: PackedScene

var spawn_timer: float = 9.0
var train_colors := [Color("#c0392b"), Color("#2980b9"), Color("#27ae60"), Color("#f39c12"), Color("#1a1a1a")]

func _process(delta: float) -> void:
	if GameManager.state != GameManager.State.PLAY:
		return

	spawn_timer -= delta
	if spawn_timer <= 0:
		spawn_train()
		var dist_factor := minf(GameManager.total_distance / 20000.0, 0.4)
		spawn_timer = randf_range(8.0, 14.0) * (1.0 - dist_factor)

func spawn_train() -> void:
	if not train_scene:
		return
	var train: Node2D = train_scene.instantiate()
	train.train_color = train_colors[randi() % train_colors.size()]

	var two_lane := randf() < 0.45
	if two_lane:
		train.train_width = 2
		train.lane = -1 if randf() < 0.5 else 0
		train.num_cars = randi_range(2, 4)
	else:
		train.train_width = 1
		train.lane = randi_range(-1, 1)
		train.num_cars = randi_range(1, 5) if randf() < 0.3 else randi_range(1, 2)
		train.climbable = randf() < 0.35

	train.depth = 0.02
	add_child(train)

