	_update_jump(delta)
	_update_slide(delta)
	_update_position()
	_check_combo(delta)

func _update_power_up_timers(delta: float) -> void:
	var changed := false
	if magnet_timer > 0:
		magnet_timer -= delta
		if magnet_timer <= 0:
			magnet_active = false
			changed = true
	if double_coin_timer > 0:
		double_coin_timer -= delta
		if double_coin_timer <= 0:
