	var pos := Perspective.depth_to_position(current_lane, 0.62)
	position.x = pos["x"]
	position.y = pos["y"] + jump_height * 0.3

func _draw() -> void:
	var u: float = get_viewport().get_visible_rect().size.x * 0.028
	var body_color := Color(0.18, 0.55, 0.91, 1.0)
	var invincible := fmod(Time.get_ticks_msec() * 0.01, 1.0) > 0.5 if invincible_timer > 0 else false

	if invincible:
		return

	match action:
		Action.RUN:
			var leg_swing := sin(Time.get_ticks_msec() * 0.012) * u * 0.8
			draw_rect(Rect2(-u * 1.2, -u * 2.8, u * 2.4, u * 2.0), body_color)
			draw_circle(Vector2(0, -u * 3.2), u * 1.1, Color(1.0, 0.85, 0.73, 1.0))
			draw_rect(Rect2(-u * 0.8, u * 0.4, u * 0.5, u * 1.8), Color(0.2, 0.2, 0.25, 1.0))
			draw_rect(Rect2(u * 0.3, u * 0.4, u * 0.5, u * 1.8), Color(0.2, 0.2, 0.25, 1.0))
			draw_rect(Rect2(-u * 1.0, -u * 1.5 + leg_swing, u * 0.5, u * 1.5), Color(0.2, 0.2, 0.25, 1.0))
			draw_rect(Rect2(u * 0.5, -u * 1.5 - leg_swing, u * 0.5, u * 1.5), Color(0.2, 0.2, 0.25, 1.0))
		Action.JUMP:
			draw_rect(Rect2(-u * 1.2, -u * 2.8, u * 2.4, u * 1.8), body_color)
			draw_circle(Vector2(0, -u * 3.2), u * 1.1, Color(1.0, 0.85, 0.73, 1.0))
			draw_rect(Rect2(-u * 1.5, -u * 2.0, u * 0.5, u * 1.2), Color(0.2, 0.2, 0.25, 1.0))
			draw_rect(Rect2(u * 1.0, -u * 2.0, u * 0.5, u * 1.2), Color(0.2, 0.2, 0.25, 1.0))
			draw_rect(Rect2(-u * 0.6, -u * 0.5, u * 1.2, u * 1.2), Color(0.2, 0.2, 0.25, 1.0))
		Action.SLIDE:
			draw_rect(Rect2(-u * 1.5, -u * 1.5, u * 3.0, u * 1.5), body_color)
